INSERT INTO "refs_biology"."sampling_methods_for_sampling_collections" AS t ("code", "code_orig", "name_en", "name_fr", "description_en", "description_fr") OVERRIDING SYSTEM VALUE VALUES ('RF', 'SRF', 'Systematic random sampling (fixed number per species)', 'Échantillonnage aléatoire systématique (nombre fixe par espèce)', 'Individuals are selected systematically at random, with a fixed number sampled for each species', 'Les individus sont sélectionnés de manière aléatoire systématique, avec un nombre fixe d''individus échantillonnés pour chaque espèce') ON CONFLICT ("code") DO UPDATE SET "code_orig" = EXCLUDED."code_orig", "name_en" = EXCLUDED."name_en", "name_fr" = EXCLUDED."name_fr", "description_en" = EXCLUDED."description_en", "description_fr" = EXCLUDED."description_fr" WHERE (t."code_orig", t."name_en", t."name_fr", t."description_en", t."description_fr") IS DISTINCT FROM (EXCLUDED."code_orig", EXCLUDED."name_en", EXCLUDED."name_fr", EXCLUDED."description_en", EXCLUDED."description_fr");
INSERT INTO "refs_biology"."sampling_methods_for_sampling_collections" AS t ("code", "code_orig", "name_en", "name_fr", "description_en", "description_fr") OVERRIDING SYSTEM VALUE VALUES ('RM', 'SRM', 'Systematic random sampling (mixed species)', 'Échantillonnage aléatoire systématique (espèces mixtes)', 'Individuals are selected systematically at random from the catch without species-specific quotas', 'Les individus sont sélectionnés de manière aléatoire systématique dans la capture sans quota spécifique par espèce') ON CONFLICT ("code") DO UPDATE SET "code_orig" = EXCLUDED."code_orig", "name_en" = EXCLUDED."name_en", "name_fr" = EXCLUDED."name_fr", "description_en" = EXCLUDED."description_en", "description_fr" = EXCLUDED."description_fr" WHERE (t."code_orig", t."name_en", t."name_fr", t."description_en", t."description_fr") IS DISTINCT FROM (EXCLUDED."code_orig", EXCLUDED."name_en", EXCLUDED."name_fr", EXCLUDED."description_en", EXCLUDED."description_fr");
INSERT INTO "refs_biology"."sampling_methods_for_sampling_collections" AS t ("code", "code_orig", "name_en", "name_fr", "description_en", "description_fr") OVERRIDING SYSTEM VALUE VALUES ('SP', 'SPS', 'Systematic proportional sampling', 'Échantillonnage systématique proportionnel', 'Individuals are selected systematically, with sample sizes proportional to the abundance of species or catch components in the catch', 'Les individus sont sélectionnés de manière systématique, les tailles d''échantillon étant proportionnelles à l''abondance des espèces ou des composantes de la capture') ON CONFLICT ("code") DO UPDATE SET "code_orig" = EXCLUDED."code_orig", "name_en" = EXCLUDED."name_en", "name_fr" = EXCLUDED."name_fr", "description_en" = EXCLUDED."description_en", "description_fr" = EXCLUDED."description_fr" WHERE (t."code_orig", t."name_en", t."name_fr", t."description_en", t."description_fr") IS DISTINCT FROM (EXCLUDED."code_orig", EXCLUDED."name_en", EXCLUDED."name_fr", EXCLUDED."description_en", EXCLUDED."description_fr");
INSERT INTO "refs_biology"."sampling_methods_for_sampling_collections" AS t ("code", "code_orig", "name_en", "name_fr", "description_en", "description_fr") OVERRIDING SYSTEM VALUE VALUES ('RP', 'SRP', 'Systematic random sampling (priority species)', 'Échantillonnage aléatoire systématique (espèces prioritaires)', 'Individuals are selected systematically at random, with sampling effort focused on predefined priority species', 'Les individus sont sélectionnés de manière aléatoire systématique, l''effort d''échantillonnage étant concentré sur des espèces prioritaires prédéfinies') ON CONFLICT ("code") DO UPDATE SET "code_orig" = EXCLUDED."code_orig", "name_en" = EXCLUDED."name_en", "name_fr" = EXCLUDED."name_fr", "description_en" = EXCLUDED."description_en", "description_fr" = EXCLUDED."description_fr" WHERE (t."code_orig", t."name_en", t."name_fr", t."description_en", t."description_fr") IS DISTINCT FROM (EXCLUDED."code_orig", EXCLUDED."name_en", EXCLUDED."name_fr", EXCLUDED."description_en", EXCLUDED."description_fr");
INSERT INTO "refs_biology"."sampling_methods_for_sampling_collections" AS t ("code", "code_orig", "name_en", "name_fr", "description_en", "description_fr") OVERRIDING SYSTEM VALUE VALUES ('SG', 'SSG', 'Stratified sampling (grab method)', 'Échantillonnage stratifié (méthode de saisie)', 'Samples are collected from predefined strata using the grab method, whereby fish are taken directly from the moving catch stream (e.g. conveyor belt, brail, sorting table)', 'Les échantillons sont prélevés dans des strates prédéfinies à l''aide de la méthode de saisie, consistant à prélever directement des poissons dans la capture pendant sa manipulation ou son traitement') ON CONFLICT ("code") DO UPDATE SET "code_orig" = EXCLUDED."code_orig", "name_en" = EXCLUDED."name_en", "name_fr" = EXCLUDED."name_fr", "description_en" = EXCLUDED."description_en", "description_fr" = EXCLUDED."description_fr" WHERE (t."code_orig", t."name_en", t."name_fr", t."description_en", t."description_fr") IS DISTINCT FROM (EXCLUDED."code_orig", EXCLUDED."name_en", EXCLUDED."name_fr", EXCLUDED."description_en", EXCLUDED."description_fr");
INSERT INTO "refs_biology"."sampling_methods_for_sampling_collections" AS t ("code", "code_orig", "name_en", "name_fr", "description_en", "description_fr") OVERRIDING SYSTEM VALUE VALUES ('SS', 'SSS', 'Stratified sampling (spill method)', 'Échantillonnage stratifié  (méthode de renversement)', 'Samples are collected from predefined strata using the spill method, whereby a known quantity or portion of the catch is discharged and sampled separately', 'Les échantillons sont prélevés dans des strates prédéfinies à l''aide de la méthode de renversement, consistant à déverser une partie de la capture afin de l''échantillonner séparément') ON CONFLICT ("code") DO UPDATE SET "code_orig" = EXCLUDED."code_orig", "name_en" = EXCLUDED."name_en", "name_fr" = EXCLUDED."name_fr", "description_en" = EXCLUDED."description_en", "description_fr" = EXCLUDED."description_fr" WHERE (t."code_orig", t."name_en", t."name_fr", t."description_en", t."description_fr") IS DISTINCT FROM (EXCLUDED."code_orig", EXCLUDED."name_en", EXCLUDED."name_fr", EXCLUDED."description_en", EXCLUDED."description_fr");
