INSERT INTO "refs_biology"."sampling_protocols" AS t ("code", "code_orig", "name_en", "name_fr", "description_en", "description_fr") OVERRIDING SYSTEM VALUE VALUES ('SP', 'SPS', 'Systematic proportional sampling', 'Échantillonnage systématique proportionnel', 'Samples are collected systematically, with sample sizes proportional to the quantities represented in the catch', 'Les échantillons sont collectés de manière systématique, avec des tailles d''échantillon proportionnelles aux quantités représentées dans la capture') ON CONFLICT ("code") DO UPDATE SET "code_orig" = EXCLUDED."code_orig", "name_en" = EXCLUDED."name_en", "name_fr" = EXCLUDED."name_fr", "description_en" = EXCLUDED."description_en", "description_fr" = EXCLUDED."description_fr" WHERE (t."code_orig", t."name_en", t."name_fr", t."description_en", t."description_fr") IS DISTINCT FROM (EXCLUDED."code_orig", EXCLUDED."name_en", EXCLUDED."name_fr", EXCLUDED."description_en", EXCLUDED."description_fr");
