INSERT INTO "refs_biology"."tag_types" AS t ("code", "code_orig", "name_en", "name_fr", "description_en", "description_fr") OVERRIDING SYSTEM VALUE VALUES ('CP', 'TC', 'Conventional tag', 'Marque conventionnelle', 'External plastic spaghetti or dart tag attached to the body of the animal for identification upon recapture or resighting', 'Marque externe de type spaghetti ou à dard fixée sur le corps de l''animal afin de permettre son identification lors d''une recapture ou d''une réobservation') ON CONFLICT ("code") DO UPDATE SET "code_orig" = EXCLUDED."code_orig", "name_en" = EXCLUDED."name_en", "name_fr" = EXCLUDED."name_fr", "description_en" = EXCLUDED."description_en", "description_fr" = EXCLUDED."description_fr" WHERE (t."code_orig", t."name_en", t."name_fr", t."description_en", t."description_fr") IS DISTINCT FROM (EXCLUDED."code_orig", EXCLUDED."name_en", EXCLUDED."name_fr", EXCLUDED."description_en", EXCLUDED."description_fr");
INSERT INTO "refs_biology"."tag_types" AS t ("code", "code_orig", "name_en", "name_fr", "description_en", "description_fr") OVERRIDING SYSTEM VALUE VALUES ('ES', 'ST', 'External satellite tag', 'Marque satellite externe', 'Satellite tag externally attached to the animal, typically on the back of sea turtles or seabirds, transmitting data remotely', 'Marque satellite fixée à l''extérieur de l''animal, généralement sur le dos des tortues marines ou des oiseaux de mer, transmettant des données à distance') ON CONFLICT ("code") DO UPDATE SET "code_orig" = EXCLUDED."code_orig", "name_en" = EXCLUDED."name_en", "name_fr" = EXCLUDED."name_fr", "description_en" = EXCLUDED."description_en", "description_fr" = EXCLUDED."description_fr" WHERE (t."code_orig", t."name_en", t."name_fr", t."description_en", t."description_fr") IS DISTINCT FROM (EXCLUDED."code_orig", EXCLUDED."name_en", EXCLUDED."name_fr", EXCLUDED."description_en", EXCLUDED."description_fr");
INSERT INTO "refs_biology"."tag_types" AS t ("code", "code_orig", "name_en", "name_fr", "description_en", "description_fr") OVERRIDING SYSTEM VALUE VALUES ('IA', 'TI', 'Internal archival tag', 'Marque archive interne', 'Archival tag implanted within the body cavity that records environmental and biological data for later recovery', 'Marque archive implantée dans la cavité corporelle enregistrant des données environnementales et biologiques pour une récupération ultérieure') ON CONFLICT ("code") DO UPDATE SET "code_orig" = EXCLUDED."code_orig", "name_en" = EXCLUDED."name_en", "name_fr" = EXCLUDED."name_fr", "description_en" = EXCLUDED."description_en", "description_fr" = EXCLUDED."description_fr" WHERE (t."code_orig", t."name_en", t."name_fr", t."description_en", t."description_fr") IS DISTINCT FROM (EXCLUDED."code_orig", EXCLUDED."name_en", EXCLUDED."name_fr", EXCLUDED."description_en", EXCLUDED."description_fr");
INSERT INTO "refs_biology"."tag_types" AS t ("code", "code_orig", "name_en", "name_fr", "description_en", "description_fr") OVERRIDING SYSTEM VALUE VALUES ('MB', 'MB', 'Metal leg band', 'Bague métallique', 'Metal identification band attached to the leg of a seabird', 'Bague d''identification métallique fixée à la patte d''un oiseau marin') ON CONFLICT ("code") DO UPDATE SET "code_orig" = EXCLUDED."code_orig", "name_en" = EXCLUDED."name_en", "name_fr" = EXCLUDED."name_fr", "description_en" = EXCLUDED."description_en", "description_fr" = EXCLUDED."description_fr" WHERE (t."code_orig", t."name_en", t."name_fr", t."description_en", t."description_fr") IS DISTINCT FROM (EXCLUDED."code_orig", EXCLUDED."name_en", EXCLUDED."name_fr", EXCLUDED."description_en", EXCLUDED."description_fr");
INSERT INTO "refs_biology"."tag_types" AS t ("code", "code_orig", "name_en", "name_fr", "description_en", "description_fr") OVERRIDING SYSTEM VALUE VALUES ('MT', 'MT', 'Metal flipper tag', 'Marque métallique de nageoire', 'Metal identification tag attached to a sea turtle flipper', 'Marque d''identification métallique fixée à une nageoire de tortue marine') ON CONFLICT ("code") DO UPDATE SET "code_orig" = EXCLUDED."code_orig", "name_en" = EXCLUDED."name_en", "name_fr" = EXCLUDED."name_fr", "description_en" = EXCLUDED."description_en", "description_fr" = EXCLUDED."description_fr" WHERE (t."code_orig", t."name_en", t."name_fr", t."description_en", t."description_fr") IS DISTINCT FROM (EXCLUDED."code_orig", EXCLUDED."name_en", EXCLUDED."name_fr", EXCLUDED."description_en", EXCLUDED."description_fr");
INSERT INTO "refs_biology"."tag_types" AS t ("code", "code_orig", "name_en", "name_fr", "description_en", "description_fr") OVERRIDING SYSTEM VALUE VALUES ('OT', 'TO', 'Other tag', 'Autre marque', 'Tag type not covered by the available categories', 'Type de marque non couvert par les catégories disponibles') ON CONFLICT ("code") DO UPDATE SET "code_orig" = EXCLUDED."code_orig", "name_en" = EXCLUDED."name_en", "name_fr" = EXCLUDED."name_fr", "description_en" = EXCLUDED."description_en", "description_fr" = EXCLUDED."description_fr" WHERE (t."code_orig", t."name_en", t."name_fr", t."description_en", t."description_fr") IS DISTINCT FROM (EXCLUDED."code_orig", EXCLUDED."name_en", EXCLUDED."name_fr", EXCLUDED."description_en", EXCLUDED."description_fr");
INSERT INTO "refs_biology"."tag_types" AS t ("code", "code_orig", "name_en", "name_fr", "description_en", "description_fr") OVERRIDING SYSTEM VALUE VALUES ('PU', 'TP', 'Pop-up archival tag', 'Marque archive pop-up', 'Pop-up satellite archival tag (PSAT) attached externally and programmed to detach at a predetermined date and transmit archived data via satellite', 'Marque archive pop-up par satellite (PSAT) fixée à l''extérieur de l''animal et programmée pour se détacher à une date prédéterminée afin de transmettre les données enregistrées par satellite') ON CONFLICT ("code") DO UPDATE SET "code_orig" = EXCLUDED."code_orig", "name_en" = EXCLUDED."name_en", "name_fr" = EXCLUDED."name_fr", "description_en" = EXCLUDED."description_en", "description_fr" = EXCLUDED."description_fr" WHERE (t."code_orig", t."name_en", t."name_fr", t."description_en", t."description_fr") IS DISTINCT FROM (EXCLUDED."code_orig", EXCLUDED."name_en", EXCLUDED."name_fr", EXCLUDED."description_en", EXCLUDED."description_fr");
INSERT INTO "refs_biology"."tag_types" AS t ("code", "code_orig", "name_en", "name_fr", "description_en", "description_fr") OVERRIDING SYSTEM VALUE VALUES ('RO', 'TR', 'Rototag', 'Rototag', 'Two-piece plastic tag inserted through a fin or other body structure for individual identification', 'Marque plastique composée de deux parties insérée dans une nageoire ou une autre structure corporelle afin d''identifier individuellement l''animal') ON CONFLICT ("code") DO UPDATE SET "code_orig" = EXCLUDED."code_orig", "name_en" = EXCLUDED."name_en", "name_fr" = EXCLUDED."name_fr", "description_en" = EXCLUDED."description_en", "description_fr" = EXCLUDED."description_fr" WHERE (t."code_orig", t."name_en", t."name_fr", t."description_en", t."description_fr") IS DISTINCT FROM (EXCLUDED."code_orig", EXCLUDED."name_en", EXCLUDED."name_fr", EXCLUDED."description_en", EXCLUDED."description_fr");
INSERT INTO "refs_biology"."tag_types" AS t ("code", "code_orig", "name_en", "name_fr", "description_en", "description_fr") OVERRIDING SYSTEM VALUE VALUES ('SO', 'TS', 'Sonic tag', 'Marque acoustique', 'Acoustic transmitter implanted within the animal that emits coded signals detected by acoustic receivers', 'Émetteur acoustique implanté dans l''animal émettant des signaux codés détectés par des récepteurs acoustiques') ON CONFLICT ("code") DO UPDATE SET "code_orig" = EXCLUDED."code_orig", "name_en" = EXCLUDED."name_en", "name_fr" = EXCLUDED."name_fr", "description_en" = EXCLUDED."description_en", "description_fr" = EXCLUDED."description_fr" WHERE (t."code_orig", t."name_en", t."name_fr", t."description_en", t."description_fr") IS DISTINCT FROM (EXCLUDED."code_orig", EXCLUDED."name_en", EXCLUDED."name_fr", EXCLUDED."description_en", EXCLUDED."description_fr");
INSERT INTO "refs_biology"."tag_types" AS t ("code", "code_orig", "name_en", "name_fr", "description_en", "description_fr") OVERRIDING SYSTEM VALUE VALUES ('SP', 'TT', 'SPOT tag', 'Marque SPOT', 'Smart Position or Temperature Transmitting tag attached externally and transmitting location or environmental data whenever the animal surfaces', 'Marque SPOT (Smart Position or Temperature Transmitting) fixée à l''extérieur de l''animal et transmettant des données de position ou d''environnement chaque fois que l''animal remonte à la surface') ON CONFLICT ("code") DO UPDATE SET "code_orig" = EXCLUDED."code_orig", "name_en" = EXCLUDED."name_en", "name_fr" = EXCLUDED."name_fr", "description_en" = EXCLUDED."description_en", "description_fr" = EXCLUDED."description_fr" WHERE (t."code_orig", t."name_en", t."name_fr", t."description_en", t."description_fr") IS DISTINCT FROM (EXCLUDED."code_orig", EXCLUDED."name_en", EXCLUDED."name_fr", EXCLUDED."description_en", EXCLUDED."description_fr");
